assert(numberOfChecks % 2 == 1);
int inside = 0, outside = 0;
double distx = bb.maxX() - bb.minX();
double disty = bb.maxY() - bb.minY();
double distz = bb.maxZ() - bb.minZ();
for (int i = 0; i < numberOfChecks; i++) {
    Point3d boundingPoint;
    double n1, n2;
    int side = std::rand()%6;
    switch(side % 3){
        case 0: 
            n1 = (double)std::rand()/((double)RAND_MAX/disty) + bb.minY();
            n2 = (double)std::rand()/((double)RAND_MAX/distz) + bb.minZ();
            boundingPoint.setY(n1);
            boundingPoint.setZ(n2);
            break;
        case 1: 
            n1 = (double)std::rand()/((double)RAND_MAX/distx) + bb.minX();
            n2 = (double)std::rand()/((double)RAND_MAX/distz) + bb.minZ();
            boundingPoint.setX(n1);
            boundingPoint.setZ(n2);
            break;
        case 2: 
            n1 = (double)std::rand()/((double)RAND_MAX/distx) + bb.minX();
            n2 = (double)std::rand()/((double)RAND_MAX/disty) + bb.minY();
            boundingPoint.setX(n1);
            boundingPoint.setY(n2);
            break;
    }
    int numIntersected = numberIntersectedPrimitives(p, boundingPoint);
    if (numIntersected % 2 == 1) {
        inside++;
    } else {
        outside++;
    }
}
return inside > outside;

